int main(){using namespace g9;CommandPolicy p;CHECK(p.classify({"cmake","--build","build"})==CommandClass::known_safe);CHECK(p.risk({"cmake","--build","build"})==RiskClass::execute);CHECK(p.classify({"mystery-tool","x"})==CommandClass::ask);CHECK(p.risk({"mystery-tool","x"})==RiskClass::execute_approval);CHECK(p.classify({"make","clean"})==CommandClass::destructive);CHECK(p.classify({"git","status"})==CommandClass::known_safe);CHECK(p.classify({"git","reset","--hard"})==CommandClass::destructive);CHECK(p.classify({"curl","https://x"})==CommandClass::denied);CHECK(p.risk({"curl","https://x"})==RiskClass::forbidden);ProcessSpec s{{"/usr/bin/printf","hello world"},"/tmp",std::chrono::milliseconds(1000),1024,minimal_environment("/tmp","/tmp")};auto r=run_process(s);CHECK_EQ(r.exit_code,0);CHECK_EQ(r.stdout_text,std::string("hello world"));ProcessSpec q{{"/usr/bin/printf","%s","a && b"},"/tmp",std::chrono::milliseconds(1000),1024,minimal_environment("/tmp","/tmp")};CHECK_EQ(run_process(q).stdout_text,std::string("a && b"));return test_support::finish();}
